import{_ as s,C as a,o as c,c as g,aj as e,E as n,j as r,a as o}from"./framework.js";const f=JSON.parse('{"title":"优惠折扣 | Cms / Commerce | Documentation","description":"配置站点 折扣规则：可 自动 在满足条件时生效，或通过 折扣码 由顾客/后台在 购物车 中输入。结账与购物车试算由服务端折扣引擎统一计算，脚本 API 见 k.commerce.discount。","frontmatter":{"title":"优惠折扣 | Cms / Commerce | Documentation","description":"配置站点 折扣规则：可 自动 在满足条件时生效，或通过 折扣码 由顾客/后台在 购物车 中输入。结账与购物车试算由服务端折扣引擎统一计算，脚本 API 见 k.commerce.discount。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/commerce/discounts.html"}]]},"headers":[],"relativePath":"zh/cms/commerce/discounts.md","filePath":"cms/commerce/discounts.md","lastUpdated":1780452103000}'),i={name:"zh/cms/commerce/discounts.md"};function l(h,t,m,u,b,p){const d=a("DocImage");return c(),g("div",null,[t[0]||(t[0]=e('<h1 id="优惠折扣" tabindex="-1">优惠折扣 <a class="header-anchor" href="#优惠折扣" aria-label="Permalink to &quot;优惠折扣&quot;">​</a></h1><blockquote><p>菜单：<strong>电商 → 优惠折扣</strong><br> 深链：<code>/_Admin/commerce/discounts?SiteId={站点GUID}</code><br><strong>新建</strong>：<code>/_Admin/commerce/discounts/create?SiteId=...</code><br><strong>编辑</strong>：<code>/_Admin/commerce/discounts/edit?SiteId=...&amp;id={折扣Id}</code></p></blockquote><p>配置站点 <strong>折扣规则</strong>：可 <strong>自动</strong> 在满足条件时生效，或通过 <strong>折扣码</strong> 由顾客/后台在 <a href="./carts.html">购物车</a> 中输入。结账与购物车试算由服务端折扣引擎统一计算，脚本 API 见 <a href="/kb-docs/zh/api/commerce/discount.html">k.commerce.discount</a>。</p><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>电商 → 优惠折扣</strong>（及父级 <strong>电商</strong>）。</li><li>左侧 <strong>电商 → 优惠折扣</strong>。</li></ol><h2 id="列表页" tabindex="-1">列表页 <a class="header-anchor" href="#列表页" aria-label="Permalink to &quot;列表页&quot;">​</a></h2><p>路径：<code>/_Admin/commerce/discounts?SiteId=...</code></p><table tabindex="0"><thead><tr><th>列 / 操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>标题</strong></td><td>规则名称（<code>title</code>）</td></tr><tr><td><strong>折扣码</strong></td><td>方式为 <strong>折扣码</strong> 时以标签展示 <code>code</code>；自动折扣为空</td></tr><tr><td><strong>条件</strong></td><td>多条条件摘要，行间以 <strong>且</strong> / <strong>或</strong> 连接</td></tr><tr><td><strong>优先级</strong></td><td>数字 <code>priority</code>，多条规则同时命中时的排序依据</td></tr><tr><td><strong>互斥</strong></td><td><strong>是</strong> 表示与其它折扣 <strong>互斥</strong>（<code>isExclusion</code>）</td></tr><tr><td><strong>生效时间</strong></td><td>开始 ~ 结束；未开始 / 进行中 / 已过期以颜色区分</td></tr><tr><td><strong>使用量</strong></td><td>折扣码已用次数；若设上限显示 <code>已用/上限</code></td></tr><tr><td><strong>详情</strong></td><td>标签：<strong>商品</strong> / <strong>订单</strong> / <strong>免运费</strong>，以及 <code>-金额</code> 或 <code>-百分比</code></td></tr><tr><td><strong>创建</strong></td><td>进入 <a href="#新建与编辑">新建与编辑</a></td></tr><tr><td><strong>已折扣订单</strong></td><td>行内搜索图标，打开 <a href="#已折扣订单弹窗">已折扣订单弹窗</a></td></tr><tr><td><strong>编辑</strong></td><td>行内铅笔进入编辑页</td></tr><tr><td><strong>批量删除</strong></td><td>勾选多行 → <strong>删除</strong> → 确认</td></tr></tbody></table>',8)),n(d,{src:"/cms/commerce/discounts-list.png",alt:"优惠折扣列表：折扣码、条件、优先级与使用量",width:"1120"}),t[1]||(t[1]=e('<h3 id="已折扣订单弹窗" tabindex="-1">已折扣订单弹窗 <a class="header-anchor" href="#已折扣订单弹窗" aria-label="Permalink to &quot;已折扣订单弹窗&quot;">​</a></h3><p>在列表行点击 <strong>已折扣订单</strong>（高级搜索图标）打开弹窗，分页展示应用了该规则的 <a href="./orders.html">订单</a>：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td><strong>订单号</strong></td><td>订单 Id</td></tr><tr><td><strong>总金额</strong></td><td>含原价/现价展示（<code>CurrencyAmount</code>）</td></tr><tr><td><strong>订单状态</strong></td><td>状态组件</td></tr><tr><td><strong>顾客</strong></td><td>邮箱、电话</td></tr><tr><td><strong>创建时间</strong></td><td>下单时间</td></tr></tbody></table>',3)),n(d,{src:"/cms/commerce/discounts-orders-dialog.png",alt:"已折扣订单弹窗：订单列表与分页",width:"960"}),t[2]||(t[2]=r("h2",{id:"新建与编辑",tabindex:"-1"},[o("新建与编辑 "),r("a",{class:"header-anchor",href:"#新建与编辑","aria-label":'Permalink to "新建与编辑"'},"​")],-1)),t[3]||(t[3]=r("p",null,[o("路径："),r("code",null,"/_Admin/commerce/discounts/create?SiteId=..."),o(" 或 "),r("code",null,".../edit?SiteId=...&id=...")],-1)),t[4]||(t[4]=r("p",null,[o("页顶面包屑 "),r("strong",null,"优惠折扣 → 创建 / 编辑"),o("。表单分三块卡片。")],-1)),n(d,{src:"/cms/commerce/discounts-edit.png",alt:"优惠折扣编辑：标题、方式、类型、条件",width:"1120"}),t[5]||(t[5]=e('<h3 id="基础信息" tabindex="-1">基础信息 <a class="header-anchor" href="#基础信息" aria-label="Permalink to &quot;基础信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>标题</strong></td><td>规则名称，列表与后台识别用</td></tr><tr><td><strong>生效时间</strong></td><td>开始、结束日期时间；超出区间规则不生效</td></tr><tr><td><strong>优先级</strong></td><td>整数，多条规则同时满足时用于排序</td></tr><tr><td><strong>方式</strong></td><td><strong>自动折扣</strong>：满足条件即参与试算；<strong>折扣码</strong>：须输入码（见下）</td></tr><tr><td><strong>折扣码</strong></td><td>仅 <strong>折扣码</strong> 方式显示：码文本（新建页可自动生成 6 位大写）、可选 <strong>限制使用次数</strong> 及次数上限</td></tr><tr><td><strong>互斥</strong></td><td>开启后与其它折扣互斥（<code>isExclusion</code>）</td></tr></tbody></table><p>购物车 <a href="./carts.html#优惠码">商品表下方的优惠码</a> 仅能选用此处 <strong>折扣码</strong> 方式且已保存的规则。</p><h3 id="优惠类型与面额" tabindex="-1">优惠类型与面额 <a class="header-anchor" href="#优惠类型与面额" aria-label="Permalink to &quot;优惠类型与面额&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>商品减价</strong>（<code>ProductAmountOff</code>）</td><td>对符合条件的 <strong>订单行</strong> 减价；条件 schema 为「订单商品」维度</td></tr><tr><td><strong>订单减价</strong>（<code>OrderAmountOff</code>）</td><td>对整单减价；条件 schema 为「订单」维度</td></tr><tr><td><strong>免运费</strong>（<code>FreeShipping</code>）</td><td>减免运费，不配置金额/百分比</td></tr></tbody></table><p>非免运费时可选 <strong>按金额</strong> 或 <strong>按百分比</strong>，并填写 <code>value</code>（后缀为站点 <code>currencyCode</code> 或 <code>%</code>）。</p><p>切换 <strong>类型</strong> 会清空已有 <strong>条件</strong> 并重新加载对应条件字段列表。</p><h3 id="适用条件" tabindex="-1">适用条件 <a class="header-anchor" href="#适用条件" aria-label="Permalink to &quot;适用条件&quot;">​</a></h3><p>使用通用 <strong>条件</strong> 组件（<code>Condition</code>）：</p><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td><strong>匹配</strong></td><td><strong>满足全部条件</strong>（且）或 <strong>满足任一条件</strong>（或）</td></tr><tr><td><strong>条件行</strong></td><td>字段（下拉，随类型变化）+ 比较方式 + 值；可 <strong>添加</strong> / <strong>删除</strong> 行</td></tr></tbody></table><p>例如可限制最低订单金额、指定商品/分类、顾客标签等（可选字段由服务端 <code>getOrderLineSchemas</code> / <code>getOrderSchemas</code> 提供）。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./carts.html">购物车</a> — 试算时输入折扣码</li><li><a href="./orders.html">订单</a> — 成交后查看已折扣订单</li><li><a href="./product-management.html">商品管理</a>、<a href="./product-categories.html">商品分类</a> — 条件常引用商品范围</li><li><a href="/kb-docs/zh/api/commerce/discount.html">k.commerce.discount</a></li></ul>',13))])}const k=s(i,[["render",l]]);export{f as __pageData,k as default};
